    private string GetPreviewStyle()
    {
        var bg = _theme switch
        {
            "Dark" => "background-color:#1e1e1e;color:#fff;",
            "Light" => "background-color:#fff;color:#333;",
            _ => "background-color:#f8f9fa;color:#333;"
        };

        var fs = _fontSize switch
        {
            "Small" => "font-size:0.85rem;",
            "Large" => "font-size:1.2rem;",
            _ => "font-size:1rem;"
        };

        var padding = _compactMode ? "padding:0.5rem;" : "padding:1rem;";

        return $"{bg}{fs}{padding}";
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _settings = updated;
    }
}

