{"file_text": "@namespace sv_666a15696dc045419649d9b158c1e623.Components.Pages.Settings
@using sv_666a15696dc045419649d9b158c1e623.Services

<div class="settings-section">
    <h3>Security Settings</h3>

    @if (_settings is null)
    {
        <p>Loading...</p>
        return;
    }

    <!-- Change Password Panel -->
    <div class="card mb-4">
        <div class="card-header d-flex justify-content-between align-items-center"
             style="cursor:pointer" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>Change Password</span>
            <span>@(_passwordExpanded ? "▲" : "▼")</span>
        </div>
        @if (_passwordExpanded)
        {
            <div class="card-body">
                @if (!string.IsNullOrEmpty(_passwordMessage))
                {
                    <div class="alert @(_passwordSuccess ? "alert-success" : "alert-danger")">@_passwordMessage</div>
                }
                <div class="mb-3">
                    <label class="form-label">Current Password</label>
                    <input type="password" class="form-control" @bind="_currentPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">New Password</label>
                    <input type="password" class="form-control" @bind="_newPassword" />
                </div>
                <div class="mb-3">
                    <label class="form-label">Confirm Password</label>
                    <input type="password" class="form-control" @bind="_confirmPassword" />
                </div>
                <button class="btn btn-primary" @onclick="ChangePasswordAsync">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="card mb-4">
        <div class="card-body d-flex justify-content-between align-items-center">
            <div>
                <strong>Two-Factor Authentication</strong>
                <span class="badge @(_settings.TwoFactorEnabled ? "bg-success" : "bg-secondary") ms-2">
                    @(_settings.TwoFactorEnabled ? "Enabled" : "Disabled")
                </span>
            </div>
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" checked="@_settings.TwoFactorEnabled" disabled />
            </div>
        </div>
    </div>

    <!-- Active Sessions -->
    <div class="card mb-4">
        <div class="card-header">Active Sessions</div>
        <div class="card-body">
            <table class="table table-hover">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th>Action</th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _settings.Sessions)
                    {
                        <ActiveSessionRow Session="session"
                                          IsCurrentSession="@(session.Id == _currentSessionId)"
                                          OnRevokeRequested="ConfirmRevoke" />
                    }
                </tbody>
            </table>
        </div>
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke is not null)
    {
        <div class="modal d-block" tabindex="-1" style="background-color:rgba(0,0,0,0.5)">
            <div class="modal-dialog">
                <div class="modal-content">
                    <div class="modal-header">
                        <h5 class="modal-title">Confirm Session Revocation</h5>
                        <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                    </div>
                    <div class="modal-body">
                        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> from <strong>@_sessionToRevoke.Location</strong>?</p>
                    </div>
                    <div class="modal-footer">
                        <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        <button class="btn btn-danger" @onclick="RevokeConfirmedAsync">Revoke Session</button>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public ISettingsService SettingsService { get; set; } = default!;

    private SecuritySettings? _settings;
    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string? _passwordMessage;
    private bool _passwordSuccess;
    private ActiveSession? _sessionToRevoke;

    // First session is treated as the current one
    private string _currentSessionId = "sess-1";

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task ChangePasswordAsync()
    {
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordMessage = "New password cannot be empty.";
            _passwordSuccess = false;
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordMessage = "Passwords do not match.";
            _passwordSuccess = false;
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _passwordMessage = "Password updated successfully!";
        _passwordSuccess = true;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private void ConfirmRevoke(string sessionId)
    {
        _sessionToRevoke = _settings?.Sessions.FirstOrDefault(s => s.Id == sessionId);
    }

    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task RevokeConfirmedAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _settings = await SettingsService.GetSecuritySettingsAsync();
            _sessionToRevoke = null;
        }
    }
}
