+                    @foreach (var lang in _languages)
+                    {
+                        <option value="@lang">@lang</option>
+                    }
+                </select>
+            </div>
+
+            <!-- Compact Mode -->
+            <div class="mb-4">
+                <div class="form-check form-switch">
+                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
+                    <label class="form-check-label" for="compactMode">Compact Mode</label>
+                </div>
+            </div>
+
+            <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
+        </div>
+
+        <!-- Live Preview -->
+        <div class="col-md-6">
+            <h5>Preview</h5>
+            <div class="border rounded p-3" style="@GetPreviewStyle()">
+                <h6 style="margin-bottom:0.5rem;">Sample Heading</h6>
+                <p style="margin-bottom:0.5rem;">This is how your content will look with the selected settings.</p>
+                <button class="btn btn-sm btn-primary">Sample Button</button>
+                @if (_compactMode)
+                {
+                    <p class="text-muted mt-2 small">Compact mode is on — reduced spacing.</p>
+                }
+            </div>
+        </div>
+    </div>
+</div>
+
+@code {
+    [Parameter] public ISettingsService SettingsService { get; set; } = default!;
+
+    private AppearanceSettings? _settings;
+    private string _theme = "Light";
+    private string _fontSize = "Medium";
+    private string _language = "English";
+    private bool _compactMode;
+
+    private static readonly string[] _themes = { "Light", "Dark", "System" };
+    private static readonly string[] _fontSizes = { "Small", "Medium", "Large" };
+    private static readonly string[] _languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese" };
+
+    protected override async Task OnInitializedAsync()
+    {
+        _settings = await SettingsService.GetAppearanceAsync();
+        _theme = _settings.Theme;
+        _fontSize = _settings.FontSize;
+        _language = _settings.Language;
+        _compactMode = _settings.CompactMode;
+    }
+
+    private string GetPreviewStyle()
+    {
+        var bg = _theme switch
+        {
+            "Dark" => "background-color:#1e1e1e;color:#fff;",
+            "Light" => "background-color:#fff;color:#333;",
+            _ => "background-color:#f8f9fa;color:#333;"
+        };
+
+        var fs = _fontSize switch
+        {
+            "Small" => "font-size:0.85rem;",
+            "Large" => "font-size:1.2rem;",
+            _ => "font-size:1rem;"
+        };
+
+        var padding = _compactMode ? "padding:0.5rem;" : "padding:1rem;";
+
+        return $"{bg}{fs}{padding}";
+    }
+
+    private async Task SaveAsync()
+    {
+        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
+        await SettingsService.SaveAppearanceAsync(updated);
+        _settings = updated;
+    }
+}
+

