@page "/settings"
@namespace sv_666a15696dc045419649d9b158c1e623.Components.Pages.Settings
@using sv_666a15696dc045419649d9b158c1e623.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetSection" />

    <main class="settings-content">
