.settings-dashboard {
    display: flex;
    min-height: 80vh;
    gap: 0;
}

.settings-sidebar {
    width: 220px;
    border-right: 1px solid #dee2e6;
    padding: 1rem 0;
    background-color: #f8f9fa;
    flex-shrink: 0;
}

